// Ensure we are not destroying an interface that is currently installed for this thread.
// If installed, we'd leave a dangling thread-local pointer in Util::interface_log.
int installed = FUZZ_GET_ATTR_INT(iface, "installed");
if (installed) { FUZZ_BAIL(); }

// Requirement: iface must be a valid, fully constructed derived instance.
// Invoke polymorphic destruction via delete-through-base to run the derived dtor then base dtor.
// After this call, iface must not be used again; we intentionally do not return it as an output.
// The fuzzer runtime will drop it from the pool as there are no outputs.
delete iface;

// No outputs returned; ownership relinquished and object destroyed.

// Install a temporary per-thread logging backend and exercise Util::interface_log
// with valid tag/fmt/args combinations. We persist the backend via outputs to
// ensure its lifetime extends beyond this call, satisfying API requirements.

// Simple concrete backend implementing the abstract interface.
class FuzzLogger : public Util::LoggingInterface {
public:
    bool log(const char *tag, const char *fmt, va_list va) override {
        // Validate required inputs are non-null C strings.
        if (!tag || !fmt) return false;
        // Attempt to format into a small bounded buffer to exercise va_list handling.
        char buf[256];
        buf[0] = '\0';
        vsnprintf(buf, sizeof(buf), fmt, va);
        // Arbitrary handling rule: handle if tag length is even to explore both true/false paths.
        size_t len = strlen(tag);
        return (len % 2) == 0;
    }
};

// Create and install the logger for this thread.
Util::LoggingInterface *installed_iface = new FuzzLogger();
Util::set_thread_logging_interface(installed_iface);
FUZZ_SET_ATTR_INT(installed_iface, "installed", 1);

// Generate a valid tag string.
std::string tag_str = FUZZ_PARAM_STR();
const char *tag = tag_str.c_str();

// Choose among known-safe printf formats and provide matching variadic args.
unsigned int mode = *FUZZ_PARAM(unsigned int) % 4u;
bool handled = false;
if (mode == 0u) {
    // No specifiers.
    handled = Util::interface_log(tag, "plain message without specifiers");
} else if (mode == 1u) {
    // Single integer specifier.
    int v = (int)(*FUZZ_PARAM(unsigned int) & 0x7fffffff);
    handled = Util::interface_log(tag, "int value: %d", v);
} else if (mode == 2u) {
    // Single string specifier; keep the backing std::string alive across the call.
    std::string s = FUZZ_PARAM_STR();
    handled = Util::interface_log(tag, "string: %s", s.c_str());
} else {
    // Multiple specifiers of well-defined types.
    unsigned int x = *FUZZ_PARAM(unsigned int);
    size_t n = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u);
    handled = Util::interface_log(tag, "hex=%x size=%zu", x, n);
}

// Property check: interface_log returns whatever the backend decides. We can't assert
// a specific value here, but we ensure the call path is valid and non-crashing.
(void)handled;

// Persist installed_iface by returning it as an output so its lifetime exceeds
// any subsequent interface_log calls from other stubs.

// Install the provided interface for the current thread. The object is user-managed,
// so we do not delete it here and must return it as an output to keep it alive in the pool.
// Mark it as installed to prevent accidental destruction while active.

if (!iface) { FUZZ_BAIL(); }
Util::set_thread_logging_interface(iface);
FUZZ_SET_ATTR_INT(iface, "installed", 1);

// Return iface as an output to maintain its lifetime across stubs.

// Call Internal::is_debugged() and assert result is stable within the same process
// due to internal static caching semantics in the provided implementation.
bool a = Internal::is_debugged();
bool b = Internal::is_debugged();
FUZZ_ASSERT(a == b, "is_debugged() must be stable within a process");

